{
  "name": "rf_init_check",
  "confidence": "medium",
  "docstring": "Checks an RF initialization/calibration flag, applies channel settings through rf_set_channel and stores a duplicated byte result when the flag is set, otherwise initializes flash for RF data when the signed status/temperature word is negative.",
  "subsystem": "rf",
  "var_renames": {
    "v2": "rf_channel_ctx",
    "v3": "rf_set_channel_ret"
  },
  "struct_hints": [
    {
      "offset": 32,
      "meaning": "Pointer field in first context/message argument referencing nested RF/channel state"
    },
    {
      "offset": 44,
      "meaning": "Pointer field at the +32 target leading to an RF channel configuration context"
    },
    {
      "offset": 20,
      "meaning": "Packed RF channel word: bits [6:0] channel number, bits [13:11] selected subchannel or band field"
    },
    {
      "offset": 36,
      "meaning": "Halfword field written with the low byte of rf_set_channel return duplicated"
    },
    {
      "offset": 72,
      "meaning": "Field in first pointer argument used to derive the third rf_set_channel argument"
    },
    {
      "offset": 197,
      "meaning": "Global byte flag relative to off_11DAB8 indicating RF initialization/calibration readiness"
    }
  ]
}
